import { useFlag } from '@openfeature/react-sdk';
import { CheckoutV1 } from './CheckoutV1';
import { CheckoutV2 } from './CheckoutV2';

export function CheckoutPage() {
  const { value: isCheckoutV2Enabled } = useFlag('checkout-v2-redesign', false);
  // Flag evaluates server-side targeting rules:
  // - 10% of all users → CheckoutV2 (new redesign)
  // - 90% of all users → CheckoutV1 (stable version)
  // Kill switch: set flag value to false → instant 100% rollback
  if (isCheckoutV2Enabled) {
    return <CheckoutV2 />;  // New redesign: 10% of traffic
  }
  return <CheckoutV1 />;    // Stable baseline: 90% of traffic
}
